function petOf(i){return S.heroes[i].pet===null?null:S.pets.find(p=>p.id===S.heroes[i].pet)||null}
function stats(i){const h=S.heroes[i],d=HEROES[i],pet=petOf(i),pd=pet?PETS[pet.type]:null,ps=pet?1+(pet.lv-1)*.18:0;
 const v=h.bonus.map((n,k)=>d.base[k]+Math.floor(d.growth[k]*(h.lv-1))+n+(pd?.all?Math.round(pd.all*ps):0));if(pd)v[1]+=Math.round(pd.int*ps);
 let attack=9+h.lv*2+v[{str:0,int:1,agi:2}[d.main]]*1.5+(pd?pd.atk*ps:0),armor=v[2]*.17+(pd?pd.armor*ps:0),spell=0,hp=95+v[0]*11+(pd?pd.hp*ps:0);
 for(let eq of h.gear)if(eq){if(eq.slot===0)attack+=eq.power;if(eq.slot===1){armor+=eq.power*.45;hp+=eq.power*5}if(eq.slot===2)spell+=eq.power}
 return {str:v[0],int:v[1],agi:v[2],hp:Math.round(hp),mp:70+v[1]*5,atk:Math.round(attack),armor:Math.round(armor*10)/10,spell,crit:Math.min(.45,.04+v[2]*.004+(pd?.crit||0)),speed:170+Math.min(45,v[2]*.8)+(pd?pd.speed+pet.lv*2:0),interval:Math.max(.45,1.05-v[2]*.008),range:i===0||i===4?86:290}}
