function makeEnemy(z,boss,x,y,id){const hp=boss?820+z*670:70+z*52;return {id:z+'-'+id,z,boss,x,y,home:{x,y},hp,max:hp,atk:boss?23+z*9:9+z*4,element:ZONES[z].element,r:boss?43:20,attack:rng(.3,1),cast:boss?4:0,wind:null,dead:false,respawn:0,slow:0,root:0,burn:0,burnTick:0,burnPower:0,taunt:0,aggro:0,drop:false}}
