baseMove=function(a,dx,dy,speed,dt){const length=Math.hypot(dx,dy);if(length<.001)return;const x=clamp(a.x+dx/length*speed*dt,65,WW-65),y=clamp(a.y+dy/length*speed*dt,125,WH-50);if(walkable(x,y)){a.x=x;a.y=y}else if(walkable(x,a.y))a.x=x;else if(walkable(a.x,y))a.y=y;if(Math.abs(dx)>.1)a.face=dx>0?1:-1;a.walk+=speed*dt*.045};
