bagPanel=function(){if(!S)return;const i=S.active,h=S.heroes[i];showDialog(panelHead('装备珍藏 · '+HEROES[i].name)+`<div class="loadout-header"><div class="loadout-hero" style="background-position:${i*25}% 0%"></div><div><h3>六部位 · 每槽最多一件</h3><p>装备属性始终生效。为保证角色画面完整，战场保留职业立绘，独立装备在此详细展示；可开启品质光效。</p><label><input id="gearGlow" type="checkbox" ${S.gearGlow?'checked':''}> 战场显示装备品质光效</label><p>金币 ${S.gold} · 行囊 ${S.bag.length}/60</p></div></div><div class="gear-grid">`+SLOT_ORDER.map(slot=>{const it=h.gear[slot];return `<article class="gear-card rarity-${it?.tier||0}"><small>${SLOT_NAMES[slot]}</small><div class="item-art" style="${it?gearStyle(it):''}"></div><h3>${it?itemName(it):'未装备'}</h3><p>${it?itemDescription(it):'探索地图获取此部位装备'}</p>${it?`<button data-unequip5="${slot}">卸下</button>`:''}</article>`}).join('')+'</div><div class="actions"><button id="autoEquip5">自动穿戴更强装备</button></div><h3>共享战利品</h3><div class="loot-grid">'+S.bag.map(it=>`<article class="loot-card rarity-${it.tier}"><div class="item-art" style="${gearStyle(it)}"></div><div><b>${itemName(it)}</b><p>${itemDescription(it)}</p><button data-equip5="${it.id}">装备</button><button data-sell5="${it.id}">出售 ${it.power*3}金</button></div></article>`).join('')+'</div>');$('#gearGlow').onchange=e=>{S.gearGlow=e.target.checked;saveGame(false)};$('#dialog').querySelectorAll('[data-equip5]').forEach(b=>b.onclick=()=>{equipItem(+b.dataset.equip5,i);bagPanel()});$('#dialog').querySelectorAll('[data-unequip5]').forEach(b=>b.onclick=()=>{if(S.bag.length>=60)return;const slot=+b.dataset.unequip5;S.bag.push(h.gear[slot]);h.gear[slot]=null;actors[i].hp=Math.min(actors[i].hp,stats(i).hp);saveGame(false);refreshBars();bagPanel()});$('#dialog').querySelectorAll('[data-sell5]').forEach(b=>b.onclick=()=>{const n=S.bag.findIndex(it=>it.id===+b.dataset.sell5);if(n<0)return;S.gold+=S.bag[n].power*3;S.bag.splice(n,1);saveGame(false);refreshBars();bagPanel()});$('#autoEquip5').onclick=()=>{for(let slot=0;slot<6;slot++){const best=S.bag.filter(it=>it.slot===slot).sort((a,b)=>b.power-a.power)[0];if(best&&best.power>(h.gear[slot]?.power||0))equipItem(best.id,i)}bagPanel()}};
function drawHeroCell(i,row,x,y,height,face=1){if(!heroFrames.complete||!heroFrames.naturalWidth)return false;const sw=heroFrames.naturalWidth/5,sh=heroFrames.naturalHeight/6,w=height*sw/sh;g.save();g.translate(x,y);g.scale(face,1);g.drawImage(heroFrames,i*sw,row*sh,sw,sh,-w/2,-height,w,height);g.restore();return true}
const warriorV4=drawWarrior;drawWarrior=function(a,mounted=false){if(!heroFrames.complete||!heroFrames.naturalWidth)return warriorV4(a,mounted);const p=poseFor(a,mounted);let row=mounted?5:p.attack?(a.animT>.22?3:4):p.cast?4:p.moving?1+(Math.floor((a.gait||0)*1.5)%2):0;g.save();if(a.hp<=0){g.globalAlpha=.4;g.rotate(1.1)}if(a.hitT>0)g.translate(Math.sin(a.hitT*80)*3,0);if(p.guarding){g.translate(-4,1);g.rotate(-.06)}drawHeroCell(a.i,row,0,p.bob,mounted?94:132);if(p.guarding){g.strokeStyle='#a9e7e4aa';g.lineWidth=3;g.beginPath();g.ellipse(20,-50,29,47,0,-1.4,1.4);g.stroke()}g.restore();return p};
const SADDLES=[[-10,-72],[-12,-65],[-7,-64],[7,-48],[0,-54],[-15,-63],[-16,-63],[-8,-61],[4,-47],[0,-53],[-8,-56],[12,-50]];
drawMount=function(type,a,foreground=false){const art=petArtType(type),image=type>=12?fusionAtlas:petAtlas,p=mountPose(type,a),s=SADDLES[art],columns=type>=12?3:4,rows=type>=12?1:3,index=type>=12?type-12:art;p.saddleY=s[1];p.saddleX=s[0];if(!image.complete||!image.naturalWidth)return p;const sw=image.naturalWidth/columns,sh=image.naturalHeight/rows,h=118,w=h*sw/sh,x=(index%columns)*sw,y=Math.floor(index/columns)*sh;g.save();g.translate(0,p.bob);if(foreground){g.beginPath();g.rect(28,-h,80,h);g.clip();g.drawImage(image,x,y,sw,sh,-w/2,-h,w,h)}else{g.drawImage(image,x,y,sw,sh*.79,-w/2,-h,w,h*.79);for(let j=0;j<4;j++){const phase=p.phase+(j%2)*Math.PI,offset=p.moving?Math.sin(phase)*2:0;g.drawImage(image,x+j*sw/4,y+sh*.79,sw/4,sh*.21,-w/2+j*w/4+offset,-h*.21-(p.moving?Math.max(0,Math.cos(phase))*2:0),w/4,h*.21)}if(type>=12){g.globalCompositeOperation='lighter';circle(s[0],s[1],42+Math.sin(renderClock*3)*3,PETS[type].color+'66',2);g.globalCompositeOperation='source-over'}}g.restore();return p};
