function drawNova(e){const p=1-e.t/e.max,c=HEROES[e.element]?.color||'#c5b4f2',r=e.r,high=S?.fxQuality!=='low',n=high?(e.kind==='ultimate'?60:30):12;g.save();g.translate(e.x,e.y);g.globalAlpha=Math.min(.68,e.t*1.7);g.globalCompositeOperation='source-over';const glow=g.createRadialGradient(0,0,0,0,0,r);glow.addColorStop(0,c+'44');glow.addColorStop(.4,c+'18');glow.addColorStop(1,c+'00');ellipse(0,0,r,r*.68,glow);for(let ring=0;ring<3;ring++){g.strokeStyle=c;g.lineWidth=(3-ring)*(1-p)+.5;g.beginPath();g.ellipse(0,0,r*(.3+ring*.23)*Math.min(1,p*4),r*(.2+ring*.15)*Math.min(1,p*4),0,renderClock*(ring%2?1:-1),renderClock*(ring%2?1:-1)+5.2);g.stroke()}for(let j=0;j<n;j++){const angle=j*2.399+e.element*.6,d=r*(.15+p*.82)*(j%3?1:.7),x=Math.cos(angle)*d,y=Math.sin(angle)*d*.66,lift=Math.sin(Math.min(1,p*1.7)*Math.PI)*(e.kind==='ultimate'?100:45)*(j%4/4+.5);if(e.element===0){line(x,y-lift,x+10,y-lift-28*(1-p),j%2?'#fff7c4':c,2)}else if(e.element===1){ellipse(x,y-lift,4,9,c,angle+renderClock);line(x,y,x,y-lift,c+'77',1)}else if(e.element===2){poly([[x-4,y-lift],[x,y-lift-22],[x+5,y-lift],[x,y-lift+6]],j%2?'#e5faff':c)}else if(e.element===3){g.shadowBlur=high?14:0;g.shadowColor=c;ellipse(x,y-lift,3+3*(1-p),12*(1-p)+3,j%2?'#ffe6aa':c,angle);g.shadowBlur=0}else{g.save();g.translate(x,y-lift);g.rotate(angle+p);poly([[-6,2],[-9,-10],[3,-18],[10,-3],[4,7]],j%2?'#f6d99a':c);g.restore()}}if(e.kind==='ultimate'||e.kind==='ascend'){for(let j=0;j<7;j++){const a=j*Math.PI*2/7+p*2;line(Math.cos(a)*r*.12,Math.sin(a)*r*.08,Math.cos(a)*r*.75,Math.sin(a)*r*.5,c+'66',1)}g.strokeStyle='#f3ecd9';g.lineWidth=2;g.beginPath();g.arc(0,-60,r*.3,p*6,p*6+2);g.stroke()}g.globalCompositeOperation='source-over';g.restore()}
draw=function(){renderClock+=1/60;g.save();if(screenShake>0)g.translate(Math.sin(renderClock*60)*screenShake,Math.cos(renderClock*73)*screenShake*.5);baseDraw();if(S){g.save();g.translate(-cam.x,-cam.y);for(const e of enemies)if(e.map===currentMap()&&e.wind){drawTell(e.wind,1-e.wind.t/e.wind.max);for(const extra of e.wind.extras)drawTell(extra,1-e.wind.t/e.wind.max)}for(const h of hazards){ellipse(h.x,h.y,h.r,h.r*.75,'#e5a76a33');circle(h.x,h.y,h.r,'#e6ba7766',2)}for(const e of battleFx){if(e.type==='element')drawElement(e);else if(e.type==='block'){circle(e.x,e.y,e.r,'#c7edf0',3)}else if(e.type==='missile'){const p=1-e.t/e.max,x=e.x+(e.tx-e.x)*p,y=e.y+(e.ty-e.y)*p;g.globalCompositeOperation='lighter';line(x-(e.tx-e.x)*.16,y-(e.ty-e.y)*.16,x,y,e.color,4);ellipse(x,y,5,7,'#fff1d1');g.globalCompositeOperation='source-over'}else{const p=1-e.t/e.max;g.strokeStyle=e.color;g.lineWidth=5*(1-p)+1;g.beginPath();g.arc(e.x,e.y,45+p*40,-1.1+p*2,1.2+p*2);g.stroke()}}for(const e of novaFx)drawNova(e);
 if(currentMap()===S.chapter+1&&!S.won&&!taskState().done){const task=FIELD_TASKS[S.chapter],q=taskState();task.points.forEach((p,i)=>{if(q.seen.includes(i))return;circle(p.x,p.y,22+Math.sin(renderClock*3+i)*2,'#e1d69a99',1);poly([[p.x-5,p.y],[p.x,p.y-31],[p.x+5,p.y]],'#b7d0ab');label(task.labels[i]+' · F',p.x,p.y-45,'#e5dcae',11)})}if(selectionDrag){const a=selectionDrag.start,b=selectionDrag.end;g.fillStyle='#83dab322';g.strokeStyle='#a6e8c2';g.lineWidth=1;g.fillRect(a.x,a.y,b.x-a.x,b.y-a.y);g.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y)}g.restore()}g.restore();if(menu==='gallery')renderGallery()};
function v5Help(){showDialog(panelHead('诸界远征 · 操作与成长')+'<p>WASD 操作当前英雄，点击地面下达选中成员移动命令。Shift 点击英雄追加选择，拖动空地框选；右键进攻移动。Ctrl+1/2/3 保存编队，1/2/3 召回已保存编队。</p><p>Q/E/R 主将技能，G 防御，空格闪避，T 百级转职觉醒技，H 全队药剂，F 互动。手机用摇杆和按钮；顶部「编队」可选全队或下达驻守命令。</p><p>「传送」选择已解锁独立地图；也可走近传送门按 F。河流只能经过桥梁，城墙要从门洞绕行。每图入口可休整、购买灵兽和重置副本。主线依次开放五张元素地图，30级或通关后开放裂隙。</p><p>英雄100级选择转职分支，上限提升到150；灵兽也能升到150级。两只10级以上灵兽加250金币可合体，预览后确认消耗。不同配方产生不同合体种族。</p><p>装备在独立卡片展示。战场默认隐藏碎片覆盖，保留完整职业外观，可在装备面板开启品质光效。</p>')}
